-- Helper function to set multiple highlight groups at once
local function set_hl_mutliple(groups, value)
  for _, v in pairs(groups) do
    vim.api.nvim_set_hl(0, v, value)
  end
end

-- Make selected text stand out
vim.api.nvim_set_hl(0, 'Visual', {
  bg = '#124a73',
  fg = '#cfe5ff',
})

-- Clear, bright comments
set_hl_mutliple({ 'TSComment', 'Comment' }, {
  fg = '#c2c7cf',
  italic = true,
})

-- Vibrant strings
set_hl_mutliple({ 'String', 'TSString' }, {
  fg = '#d4bee6',
})

-------------------------------------------------------------------------------
-- Brightened Syntax Elements
-------------------------------------------------------------------------------

-- 1. Control flow (ifs, elses, returns, loops, keywords)
set_hl_mutliple({
  'Keyword',
  'Conditional',
  'Repeat',
  'Statement',
  'TSKeyword',
  'TSKeywordFunction',
  'TSConditional',
  'TSRepeat',
  '@keyword',
  '@keyword.conditional',
  '@keyword.repeat',
  '@keyword.return',
}, {
  fg = '#9ccbfb',
  bold = true,
})

-- 2. Function calls & declarations
set_hl_mutliple({
  'Function',
  'TSFunction',
  'TSMethod',
  'TSFuncCall',
  'TSMethodCall',
  '@function',
  '@function.call',
  '@method',
  '@method.call',
}, {
  fg = '#d4bee6',
})

-- 3. Variable declarations & identifiers
set_hl_mutliple({
  'Identifier',
  'TSVariable',
  'TSVariableBuiltin',
  '@variable',
  '@variable.builtin',
  '@variable.parameter',
}, {
  fg = '#e0e2e8',
})

-- 4. Brackets, parentheses, delimiters & operators
set_hl_mutliple({
  'Delimiter',
  'Operator',
  'TSPunctBracket',
  'TSPunctDelimiter',
  '@punctuation.bracket',
  '@punctuation.delimiter',
  '@operator',
}, {
  fg = '#e0e2e8',
})

-------------------------------------------------------------------------------
-- Background Transparency
-------------------------------------------------------------------------------
set_hl_mutliple({ 'Normal', 'NormalNC', 'SignColumn', 'EndOfBuffer', 'NormalFloat' }, {
  bg = 'NONE',
})
